// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * The pure "when" of hedge racing. Probe hedges: with SLO budget {@code (1+rho)*K} (rho = the probe config's
 * maxSlowdownFraction, K = incumbent expected) and a backup whose conservative completion is B95 plus launch overhead
 * c, the latest SLO-compliant backup launch is {@code h_max = (1+rho)*K - B95 - c}. When {@code h_max >= D} (the
 * trial's deadline) the existing serial timeout-then-fallback path already meets the SLO and no hedge is needed;
 * otherwise the backup launches at {@code clamp(h_max, 0, D)} — as late as the SLO permits, never negative. Guard
 * triggers anchor to the WINNER's own predictive high99 (a confidently mispriced winner is provably wrong the moment it
 * outruns its own 99% bound), never to the runner-up's expectation. The conditional-remaining test asks, given the
 * primary's lognormal predictive posterior and its survival to {@code t}, whether its remaining p75 still exceeds the
 * backup's p95 completion — the report's soft trigger, computable in closed form from the posterior.
 */
final class LmdbNativeHedgePolicy {

	/** Returned when no hedge/arming applies. */
	static final long NONE = -1L;

	private LmdbNativeHedgePolicy() {
	}

	/**
	 * Backup launch delay for a probe hedge, or {@link #NONE} when the serial path already meets the SLO. An
	 * unpriceable (ORDINAL_ONLY) trial with spare hedge capacity launches at zero: the arm is being probed precisely
	 * because it cannot be priced, so a full paired race maximizes information and the waste is capped by the deadline.
	 */
	static long probeHedgeDelayNanos(double incumbentExpectedNanos, double incumbentHigh95Nanos, long deadlineNanos,
			boolean trialOrdinalOnly, boolean spareCapacity, LmdbNativeProbeConfig probeConfig,
			LmdbNativeHedgeConfig config) {
		if (deadlineNanos <= 0L || incumbentExpectedNanos <= 0.0) {
			return NONE;
		}
		double sloBudget = (1.0 + probeConfig.maxSlowdownFraction()) * incumbentExpectedNanos;
		double hMax = sloBudget - incumbentHigh95Nanos - config.launchOverheadNanos();
		if (hMax >= deadlineNanos) {
			return NONE; // serial timeout + fallback already fits the SLO
		}
		if (trialOrdinalOnly && spareCapacity) {
			return 0L;
		}
		return Math.max(0L, Math.min((long) hMax, deadlineNanos));
	}

	/**
	 * Watchdog trigger for a normal-dispatch winner, or {@link #NONE} when arming is not worth a timer (the winner's
	 * own bound is below the arming floor — the happy path for sub-floor dispatches is this one comparison). An
	 * ORDINAL_ONLY winner has no bound of its own and triggers relative to the trusted runner-up instead.
	 */
	static long guardTriggerNanos(LmdbNativeCostPrediction winner, LmdbNativeCostPrediction runnerUp,
			LmdbNativeHedgeConfig config) {
		if (runnerUp == null) {
			return NONE;
		}
		if (winner.uniformlyPriceable()) {
			double high99 = winner.high99Nanos();
			if (high99 < config.guardMinTriggerNanos()) {
				return NONE;
			}
			return (long) Math.max(high99 * config.guardTriggerMargin(), config.guardMinTriggerNanos());
		}
		double anchored = config.guardUnpricedTriggerFactor() * runnerUp.expectedNanos();
		return (long) Math.max(anchored, config.guardMinTriggerNanos());
	}

	/**
	 * The fire-time soft trigger: given the primary's survival to {@code elapsedNanos}, does its conditional remaining
	 * p-quantile still exceed the backup's conservative completion plus launch overhead? For log T ~ N(mu, s^2)
	 * conditioned on T &gt; t: {@code P(T > x | T > t) = S((ln x - mu)/s) / S(a)} with {@code a = (ln t - mu)/s}, so
	 * the conditional p-quantile is {@code exp(mu + s * inversePhi(1 - (1-p) * exp(logSurvival(a))))}. An unpriceable
	 * primary cannot be estimated — the hard trigger having fired is then the only signal, and this returns true.
	 */
	static boolean backupLikelyWins(LmdbNativeCostPrediction primary, long elapsedNanos,
			LmdbNativeCostPrediction backup, LmdbNativeHedgeConfig config) {
		if (elapsedNanos <= 0L) {
			return false;
		}
		LmdbNativeCostPrediction.Components components = primary.components();
		if (components == null) {
			return true;
		}
		double mu = components.logBase() + components.meanLog();
		double variance = components.varGlobal() + components.varFamily() + components.varExact()
				+ components.noiseVar();
		double s = Math.sqrt(Math.max(variance, 1e-12));
		double a = (Math.log(elapsedNanos) - mu) / s;
		double p = config.guardRemainingQuantile();
		// log of the conditional survival mass we must leave above the quantile, computed in log space
		double logTail = Math.log(1.0 - p) + LmdbNativeGaussianMath.logSurvival(a);
		double tailProbability = Math.exp(logTail);
		if (!(tailProbability > 0.0) || tailProbability >= 1.0) {
			return true; // survival mass degenerate: the primary has outrun its posterior entirely
		}
		// Phi^-1(1 - tail) via the symmetry -Phi^-1(tail): stable when the tail is so small that 1 - tail rounds to
		// 1.0 in double (a primary far past its posterior) — the direct form would throw a domain error there.
		double z = -LmdbNativeGaussianMath.inversePhi(tailProbability);
		double conditionalQuantile = Math.exp(mu + s * z);
		double remaining = conditionalQuantile - elapsedNanos;
		return remaining > backup.high95Nanos() + config.launchOverheadNanos();
	}

	/**
	 * A losing arm's right-censor bound: it ran uncontended on {@code [0, h)} and shared the machine with exactly one
	 * sibling on {@code [h, e]}, so its uncontended runtime is at least {@code h + (e - h) * contentionDiscount}. Valid
	 * for h = 0 (a from-the-start race still yields e/2 of evidence) and never the forbidden {@code h + backup
	 * time}.
	 */
	static long censorBoundNanos(long launchDelayNanos, long elapsedNanos, LmdbNativeHedgeConfig config) {
		if (elapsedNanos <= launchDelayNanos) {
			return elapsedNanos;
		}
		long overlap = elapsedNanos - launchDelayNanos;
		return launchDelayNanos + (long) (overlap * config.contentionDiscount());
	}

	/**
	 * Ledger reservation for a hedged probe: the trial's worst case (deadline + cancel bound) plus the worst wasted
	 * backup partial {@code (D - h)} plus interference on both arms over the worst overlap.
	 */
	static long probeHedgeReservationNanos(long deadlineNanos, long launchDelayNanos,
			LmdbNativeProbeConfig probeConfig, LmdbNativeHedgeConfig config) {
		long overlap = Math.max(0L, deadlineNanos - launchDelayNanos);
		long interference = (long) (overlap * (1.0 + 2.0 * config.interferenceFraction()));
		return saturatingAdd(saturatingAdd(deadlineNanos, probeConfig.cancelBoundNanos()), interference);
	}

	/**
	 * Ledger reservation for a guard rescue, taken at FIRE time: the whole backup may be waste (the primary can still
	 * win), so reserve its conservative completion with both-arm interference, plus the cancel bound and launch
	 * overhead.
	 */
	static long guardReservationNanos(double backupHigh95Nanos, LmdbNativeProbeConfig probeConfig,
			LmdbNativeHedgeConfig config) {
		long backup = (long) (backupHigh95Nanos * (1.0 + 2.0 * config.interferenceFraction()));
		return saturatingAdd(saturatingAdd(backup, probeConfig.cancelBoundNanos()), config.launchOverheadNanos());
	}

	private static long saturatingAdd(long a, long b) {
		long sum = a + b;
		return sum < 0L ? Long.MAX_VALUE : sum;
	}
}
